components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 16px 24px;
  background: linear-gradient(135deg, #4F46E5 0%, #7C3AED 100%);
  color: #FFFFFF;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 16px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.01em;
  border: none;
  border-radius: 9999px;
  cursor: pointer;
  box-shadow: 0 4px 20px rgba(79,70,229,0.40);
  transition: box-shadow 150ms ease, transform 150ms ease;
  -webkit-font-smoothing: antialiased;
}
.ds-btn-primary:hover {
  box-shadow: 0 6px 32px rgba(79,70,229,0.50);
}
.ds-btn-primary:active {
  transform: scale(0.98);
  box-shadow: 0 2px 10px rgba(79,70,229,0.32);
}
.ds-btn-primary:disabled {
  opacity: 0.50;
  cursor: not-allowed;
  transform: none;
  box-shadow: 0 4px 20px rgba(79,70,229,0.40);
}

.ds-btn-go-online {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 16px 24px;
  background: linear-gradient(135deg, #FB923C 0%, #F97316 100%);
  color: #FFFFFF;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
  border: none;
  border-radius: 24px;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(249,115,22,0.35);
  transition: box-shadow 150ms ease, transform 150ms ease;
  -webkit-font-smoothing: antialiased;
}
.ds-btn-go-online:hover {
  box-shadow: 0 6px 22px rgba(249,115,22,0.45);
}
.ds-btn-go-online:active {
  transform: scale(0.98);
  box-shadow: 0 2px 8px rgba(249,115,22,0.28);
}
.ds-btn-go-online:disabled {
  opacity: 0.50;
  cursor: not-allowed;
  transform: none;
}

.ds-input {
  width: 100%;
  padding: 14px 16px;
  background: #F5F7FF;
  color: #0F172A;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.5;
  border: 1px solid #E8EEFF;
  border-radius: 20px;
  outline: none;
  transition: border-color 150ms ease, box-shadow 150ms ease;
  -webkit-font-smoothing: antialiased;
}
.ds-input::placeholder {
  color: #94A3B8;
}
.ds-input:focus {
  border-color: #4F46E5;
  box-shadow: 0 0 0 3px rgba(79,70,229,0.10);
}
.ds-input.ds-input--error {
  border-color: #EF4444;
}
.ds-input.ds-input--error:focus {
  box-shadow: 0 0 0 3px rgba(239,68,68,0.10);
}

.ds-card {
  background: #FFFFFF;
  border-radius: 24px;
  padding: 16px;
  box-shadow: 0 2px 16px rgba(79,70,229,0.07);
}
.ds-card--admin {
  background: #FFFFFF;
  border-radius: 24px;
  padding: 16px;
  box-shadow: 0 1px 3px rgba(15,23,42,0.05), 0 4px 20px rgba(79,70,229,0.06);
}

.ds-pill {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: 9999px;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
  -webkit-font-smoothing: antialiased;
}
.ds-pill-success { background: #D1FAE5; color: #10B981; }
.ds-pill-warning { background: #FEF3C7; color: #F59E0B; }
.ds-pill-danger  { background: #FEE2E2; color: #EF4444; }
.ds-pill-info    { background: #E0F2FE; color: #0EA5E9; }
.ds-pill-muted   { background: #F5F7FF; color: #94A3B8; }
.ds-pill-primary { background: #EEF2FF; color: #4F46E5; }

.ds-sheet {
  background: #FFFFFF;
  border-radius: 32px 32px 0 0;
  padding: 0 16px 24px;
  box-shadow: 0 -6px 32px rgba(79,70,229,0.10);
}
.ds-sheet-handle {
  width: 40px;
  height: 4px;
  background: rgba(79,70,229,0.15);
  border-radius: 9999px;
  margin: 12px auto 16px;
}

.ds-nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  color: #94A3B8;
  cursor: pointer;
  transition: background 150ms ease, color 150ms ease;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
.ds-nav-item:hover {
  background: #F5F7FF;
  color: #475569;
}
.ds-nav-item--active {
  background: #4F46E5;
  color: #FFFFFF;
}
.ds-nav-item--active:hover {
  background: #4338CA;
  color: #FFFFFF;
}

.ds-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}
.ds-logo-word {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #0F172A;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
}
.ds-logo--white .ds-logo-word {
  color: #FFFFFF;
}
